def ultra_eq(f, g, n=10000):
    agree = sum(1 for i in range(n) if f(i) == g(i))
    density = agree / n
    return (density > 0.5, density)

def standard_part(f, n=10000):
    from collections import Counter
    vals = [f(i) for i in range(n)]
    counter = Counter(vals)
    for val, count in counter.most_common():
        if count / n > 0.5:
            return val
    return None

def overspill_bound(p, n=10000):
    def f(i):
        bound = 0
        for k in range(i + 1):
            if p(i, k):
                bound = k
            else:
                break
        return bound
    return f
